// Decides what the coach says out loud. Pure logic: returns clip ids, never plays anything.
// Clip ids match voice/clips (generated by voice/make-voice.mjs): "<group>-<n>" and "count-<n>".
// A named player also gets "name-*" clips ("Let's go, Ramy!"), made per name on the server; the
// name is used at moments that matter, not on every rep, so it stays personal instead of noise.
import {Cue, ExerciseUpdate} from './exercises/types';
import {Reward} from './rewards';
import manifest from './voiceClips.json';

type Group = keyof typeof manifest.groups;

const MAX_CLIPS = 2; // per event; more would lag behind the movement
const SAME_CUE_GAP_MS = 5000; // don't nag: the same cue at most once per 5 s
const PRAISE_EVERY = 4; // clean reps between spontaneous praise

const CUE_GROUP: Record<Cue, Group> = {
  deeper: 'cue-deeper',
  slower: 'cue-slower',
  'step-back': 'cue-step-back',
};

const REWARD_GROUP: Partial<Record<Reward['kind'], Group>> = {
  target: 'target',
  streak: 'streak',
  deepest: 'deepest',
};

export class VoiceCoach {
  private lastVariant: Partial<Record<Group, number>> = {};
  private lastCueAt: Partial<Record<Cue, number>> = {};
  private cleanSincePraise = 0;
  private praiseCount = 0;
  private saidDeeperByName = false;

  constructor(
    private readonly target: number | null = null,
    private readonly random: () => number = Math.random,
    private readonly named = false, // the player's name clips are ready to use
  ) {}

  start(): string[] {
    return [this.named ? 'name-start' : this.pick('start')];
  }

  // Between sets. Until dedicated rest lines exist, rest uses praise and the next set re-greets.
  restStart(): string[] {
    return [this.pick('praise')];
  }

  restMid(): string[] {
    return [this.pick('praise')];
  }

  nextSet(): string[] {
    return this.start();
  }

  finish(): string[] {
    return [this.named ? 'name-finish' : this.pick('finish')];
  }

  update(u: ExerciseUpdate, reward: Reward | null, t: number): string[] {
    const clips: string[] = [];

    if (u.rep && u.reps <= manifest.counts) {
      clips.push(`count-${u.reps}`);
    }

    if (u.cue && t - (this.lastCueAt[u.cue] ?? -Infinity) >= SAME_CUE_GAP_MS) {
      this.lastCueAt[u.cue] = t;
      this.cleanSincePraise = 0;
      clips.push(this.cueClip(u.cue));
      return clips.slice(0, MAX_CLIPS);
    }
    if (u.cue) {
      this.cleanSincePraise = 0;
    }
    if (!u.rep) {
      return clips;
    }

    const rewardGroup = reward ? REWARD_GROUP[reward.kind] : undefined;
    const toGo = this.target == null ? null : this.target - u.reps;
    if (rewardGroup) {
      clips.push(this.pick(rewardGroup));
      this.cleanSincePraise = 0;
    } else if (toGo === 2) {
      clips.push(this.pick('near-target-2'));
    } else if (toGo === 1) {
      clips.push(this.named ? 'name-last' : this.pick('near-target-1'));
    } else if (!u.cue && ++this.cleanSincePraise >= PRAISE_EVERY) {
      clips.push(this.named && this.praiseCount++ % 2 === 0 ? 'name-praise' : this.pick('praise'));
      this.cleanSincePraise = 0;
    }
    return clips.slice(0, MAX_CLIPS);
  }

  private cueClip(cue: Cue): string {
    if (cue === 'deeper' && this.named && !this.saidDeeperByName) {
      this.saidDeeperByName = true;
      return 'name-deeper';
    }
    return this.pick(CUE_GROUP[cue]);
  }

  // A random variant of the group, never the same one twice in a row.
  private pick(group: Group): string {
    const n = manifest.groups[group];
    let i = Math.floor(this.random() * n) + 1;
    if (n > 1 && i === this.lastVariant[group]) {
      i = (i % n) + 1;
    }
    this.lastVariant[group] = i;
    return `${group}-${i}`;
  }
}
